  "bots.setup.callbackUrlDescription.webhookBind":
    "La vinculación por Webhook usa el mismo endpoint: envía aquí una solicitud de callback privada con text = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Abre @BotFather en Telegram y crea un bot nuevo.",
  "bots.setup.guide.telegram.create.2":
    "Copia el token de la API HTTP que devuelve BotFather y pégalo en este formulario.",
