  "bots.setup.guide.weixin.bind.3":
    "Vuelve aquí cuando la vinculación se complete para terminar de configurar los valores predeterminados del espacio de trabajo y de la CLI.",
  "bots.setup.guide.feishu.create.1":
    "Crea una app propia en la consola de desarrolladores de Feishu/Lark y activa la función de bot.",
  "bots.setup.guide.feishu.create.2":
    "Copia el App ID y el App Secret y activa los eventos de conexión persistente para `im.message.receive_v1` y las acciones de tarjeta.",
  "bots.setup.guide.feishu.create.3":
    "Elige aquí el dominio correspondiente de Feishu o Lark y pega las credenciales en el formulario.",
  "bots.setup.guide.feishu.bind.1":
    "Instala la app en tu tenant y abre un chat directo con el bot.",
