  "settings.modelProvider.fieldHelp": "Información sobre {field}",
  "settings.modelProvider.help.contextWindow":
    "La capacidad de contexto que el modelo puede procesar a la vez, en tokens. DeepVibe la usa para gestionar el contexto.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.maxOutputTokens":
    "El número máximo de tokens que puede generar una sola solicitud al modelo.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.inputModalities":
    "Define los tipos de contenido que el modelo puede recibir:\n\n- **Texto**: Recibe contenido de texto. Obligatorio.\n- **Imágenes**: Recibe contenido de imagen.\n- **Vídeo**: Recibe contenido de vídeo.\n- **PDF**: Recibe documentos PDF directamente.",
  "settings.modelProvider.help.outputModalities":
    "El tipo de contenido de las respuestas del modelo. Actualmente solo se admite texto.",
  "settings.modelProvider.help.capabilities":
    "- **Salida estructurada**: Admite restricciones de JSON Schema en los campos, los tipos y la estructura de la salida.\n- **Búsqueda web nativa**: Admite la capacidad de búsqueda web integrada en la API del modelo.\n- **Mensajes de sistema durante la conversación**: Permite insertar instrucciones de sistema durante una conversación.\n\nNo actives capacidades que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Define los niveles de razonamiento disponibles en el chat. **Deben ordenarse de menor a mayor esfuerzo de razonamiento**.\nNo configures niveles de razonamiento que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Usa una expresión CEL para asignar el nivel de razonamiento actual, `reasoningLevel`, a los campos de la solicitud a la API del modelo. El objeto JSON que devuelve la expresión se combina en el cuerpo de la solicitud saliente.",
  "settings.modelProvider.help.advanced":
    "**Esquema de herramientas MFJS**: Activa la compatibilidad con Moonshot Flavored JSON Schema, que suele usar la API del modelo Kimi de Moonshot. Actívalo solo si la API del modelo requiere este formato.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Ajusta la configuración recomendada según el ID del modelo, la URL base y el formato de API. DeepVibe actualiza continuamente las recomendaciones y las sincroniza automáticamente contigo.\nSi cambias un ajuste manualmente, ese ajuste pasa a gestionarse a mano y deja de seguir las actualizaciones de las recomendaciones; los demás siguen gestionados por la configuración inteligente.",
